import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Detects explicit generation markers and unfinished implementation
 * placeholders. These are the strongest, least ambiguous signals the detector
 * has, so they carry the most weight.
 *
 * <p>Markers are not limited to ChatGPT: attributions to other assistants and
 * coding agents (Copilot, Claude Code, Gemini, Cursor, Codex, DeepSeek, Qwen,
 * Aider, Devin, ...) are recognised as well, including the common
 * {@code Co-authored-by:} and {@code @author} trailers.</p>
 */
public class AiTraitsAnalyzer implements CodeAnalyzer {

    /**
     * Assistant and model names that can appear in an attribution.
     *
     * <p>Names that are also ordinary English words are kept out of the plain
     * "generated by X" context unless the surrounding phrase is specific
     * enough (for example {@code v0.dev}, not {@code v0}).</p>
     */
    private static final String TOOLS =
            "github\\s+copilot"
                    + "|copilot-swe-agent|copilot"
                    + "|claude\\s+code|claude|anthropic"
                    + "|chatgpt|gpt[-\\w.]*|openai|codex"
                    + "|gemini|bard|google\\s+ai|vertex\\s+ai"
                    + "|cursor|windsurf|codeium|tabnine"
                    + "|amazon\\s+q|aws\\s+codewhisperer|codewhisperer"
                    + "|sourcegraph\\s+cody"
                    + "|deepseek|qwen|chatglm|ernie|doubao|kimi|minimax"
                    + "|grok|xai|llama|meta\\s+ai|mistral|codestral|perplexity"
                    + "|devin|aider|cline|roo\\s+code|kilo\\s+code|trae"
                    + "|continue\\.dev"
                    + "|bolt\\.new|lovable|v0\\.dev"
                    + "|jetbrains\\s+ai|ollama|groq|together\\s+ai"
                    + "|hugging\\s+face|openrouter|fireworks\\s+ai|replit"
                    + "|llm|large\\s+language\\s+model|ai|a\\.i\\.";

    private static final Pattern TOOL_MARKER = Pattern.compile(
            "(?:generated|written|created|produced|authored|made"
                    + "|autocompleted|suggested|assisted|powered)\\s+"
                    + "(?:by|with|using)\\s*\\[?\\s*(?:an?\\s+|the\\s+)?("
                    + TOOLS + ")(?![\\w])"
                    + "|co-authored-by:\\s*\\[?\\s*(" + TOOLS + ")(?![\\w])"
                    + "|@author\\s+(" + TOOLS + ")(?![\\w])",
            Pattern.CASE_INSENSITIVE
    );

    private static final Pattern GENERIC_MARKER = Pattern.compile(
            "(?:ai|llm)[-\\s](?:generated|assisted|powered)"
                    + "|with\\s+ai\\s+assistance"
                    + "|vibe[-\\s]coded"
                    + "|this\\s+(?:code|file|class|method)\\s+(?:was|is|has\\s+been)\\s+"
                    + "(?:auto-?)?generated"
                    + "|\\uD83E\\uDD16\\s*(?:generated|written|created)\\s+with",
            Pattern.CASE_INSENSITIVE
    );

    private static final Pattern PLACEHOLDER = Pattern.compile(
            "TODO\\s*:\\s*implement"
                    + "|TODO\\s+implement"
                    + "|implementation\\s+goes\\s+here"
                    + "|your\\s+code\\s+here"
                    + "|add\\s+your\\s+(?:code|logic)\\s+here"
                    + "|not\\s+implemented\\s+yet"
                    + "|lorem\\s+ipsum",
            Pattern.CASE_INSENSITIVE
    );

    private static final Pattern EMPTY_CATCH = Pattern.compile(
            "catch\\s*\\([^)]*\\)\\s*\\{\\s*\\}"
    );

    @Override
    public void analyze(AnalysisContext context) {

        String raw = context.getCode();
        String code = SourceText.stripCommentsAndLiterals(raw);

        // Comments are where generation markers and TODOs normally live, but
        // they must not be counted when they only appear inside a string
        // literal (test fixtures, messages, SQL).
        String prose = context.getComments() + "\n" + code;

        String marker = findMarker(prose);

        if (marker != null) {
            context.addPoints(
                    Categories.AI_TRAITS,
                    20,
                    "Explicit AI-generation marker detected: \"" + marker + "\""
            );
        }

        String placeholder = findPlaceholder(prose);

        if (placeholder != null) {
            context.addPoints(
                    Categories.AI_TRAITS,
                    6,
                    "Unfinished implementation placeholder: \"" + placeholder + "\""
            );
        }

        int unsupported = AnalyzerSupport.count(code, "UnsupportedOperationException");
        int todos = AnalyzerSupport.count(prose, "TODO");

        if (unsupported >= 2 && todos >= 2) {
            context.addPoints(
                    Categories.AI_TRAITS,
                    6,
                    "Multiple unfinished implementation indicators "
                            + "(TODO + UnsupportedOperationException)."
            );
        }

        if (EMPTY_CATCH.matcher(code).find()) {
            context.addPoints(
                    Categories.AI_TRAITS,
                    4,
                    "Empty exception-handling block detected."
            );
        }
    }

    /**
     * Returns a short description of the first generation marker found. A
     * named assistant or model is preferred over a generic phrase, so the
     * report can say which tool was credited.
     */
    private String findMarker(String source) {

        String tool = firstCaptured(TOOL_MARKER, source);

        if (tool != null) {
            return tool;
        }

        Matcher generic = GENERIC_MARKER.matcher(source);

        if (generic.find()) {
            return AnalyzerSupport.truncate(generic.group(), 40);
        }

        return null;
    }

    private String firstCaptured(Pattern pattern, String source) {

        Matcher matcher = pattern.matcher(source);

        if (!matcher.find()) {
            return null;
        }

        for (int group = 1; group <= matcher.groupCount(); group++) {
            String value = matcher.group(group);

            if (value != null) {
                return AnalyzerSupport.truncate(value, 40);
            }
        }

        return AnalyzerSupport.truncate(matcher.group(), 40);
    }

    private String findPlaceholder(String source) {

        Matcher matcher = PLACEHOLDER.matcher(source);

        if (!matcher.find()) {
            return null;
        }

        return AnalyzerSupport.truncate(matcher.group(), 60);
    }
}
